const fetchOrderDetails = async () => {
  try {
    const orderDetailsResponse = await getOrderDetails();
    setOrderDetails(orderDetailsResponse.data);
  } catch (error) {
    console.error("Order Details Error:", error);
  }
};
    

    useEffect(() => {
        fetchOrderDetails();
    }, []);

